/// behavior.
///
/// The table is append-only from a business perspective and records the
/// client context for each session together with its creation and expiration
/// timestamps. Each session belongs to exactly one {@link
/// mall_platform_customers} record.
///
/// @namespace auth
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model mall_platform_customer_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer's {@link mall_platform_customers.id}.
  mall_platform_customer_id String @db.Uuid

  /// IP address observed when the session was created.
  ip String

  /// Request URL or entry page associated with the session creation.
  href String

  /// Referrer URL recorded when the session was created.
  referrer String

  /// Timestamp when the session was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the session expires and becomes invalid.
  expired_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  customer mall_platform_customers @relation(fields: [mall_platform_customer_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@index([mall_platform_customer_id, created_at], map: "mall_platform_customer_sessions_mall_platform_customer_d2a48cd3")
}

