  mall_platform_customer_id String @db.Uuid

  /// Opaque password reset token used to verify the recovery request.
  token String

  /// Time when the password reset token expires and can no longer be used.
  expired_at DateTime @db.Timestamptz

  /// Time when the reset token was consumed, if it has already been used.
  used_at DateTime? @db.Timestamptz

  /// Timestamp when the password reset record was created.
