  mall_platform_seller_id String @db.Uuid

  /// IP address captured when the session was created.
  ip String

  /// Current page or request URL associated with the session creation context.
  href String

  /// Referrer URL captured at the time the session was created.
  referrer String

  /// Timestamp when the session was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the session expires and can no longer be used.
