  typia.assert(customer);
  const request = {
    accountType: "customer",
    accountId: customer.id,
    status: null,
    createdFrom: null,
    createdTo: null,
    expiredFrom: null,
    expiredTo: null,
    sort: null,
    page: 1,
    limit: 50,
  } satisfies IMallPlatformSellerPasswordReset.IRequest;
  const first = await api.functional.mallPlatform.customer.passwordResets.index(
    customerConnection,
    { body: request },
  );
  typia.assert(first);
