        "email",
        "id",
        "rejectionReason",
        "status",
        "updatedAt",
      ].sort(),
    );
    TestValidator.predicate(
      "reset summary does not expose secret credential fields",
      !("token" in item) &&
        !("passwordHash" in item) &&
        !("resetToken" in item),
    );
  }
}

