   * Test product image reorder success.
   *
   * Validates that an authenticated actor can reorder an existing product gallery and that the first image becomes the main thumbnail.
   *
   * 1. Register and authenticate a seller using an isolated seller connection.
   * 2. Create a product and attach multiple images in a known initial order.
   * 3. Register and authenticate a customer using an isolated customer connection.
   * 4. Reorder the images through the customer-scoped endpoint and verify the new order is reflected in the response.
   */
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "password123",
    } satisfies IMallPlatformSeller.IJoin,
  });
  const product = await generate_random_mall_platform_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.name(),
        description: RandomGenerator.paragraph({ sentences: 3 }),
        categoryId: null,
        basePrice: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1>
        >(),
      },
    },
  );
  typia.assert(product);
  const createdImages: IMallPlatformProductImage[] =
    await ArrayUtil.asyncRepeat(3, async (index) => {
      const image =
        await generate_random_mall_platform_seller_products_images_create(
          sellerConnection,
          {
            params: { productId: product.id },
            body: {
              imageUrl: `https://example.com/product-${product.id}-${index + 1}.jpg`,
              sortOrder: index,
              isMain: index === 0,
            } satisfies IMallPlatformProductImage.ICreate,
          },
        );
      typia.assert(image);
      return image;
    });
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "password123",
      href: "https://example.com/register",
      referrer: "https://example.com",
      ip: "127.0.0.1",
    } satisfies IMallPlatformCustomer.IJoin,
  });
  const reorderedImages = [
    createdImages[2],
    createdImages[0],
    createdImages[1],
  ];
  const reordered =
    await api.functional.mallPlatform.customer.products.images.index(
      customerConnection,
      {
        productId: product.id,
        body: {
          images: reorderedImages,
          page: 1,
          limit: 10,
        } satisfies IMallPlatformProductImage.IRequest,
      },
    );
  typia.assert(reordered);
  TestValidator.equals(
    "pagination page should be first page",
    reordered.pagination.current,
    1,
  );
  TestValidator.predicate(
    "reordered response should contain all images",
    reordered.data.length === createdImages.length,
  );
  TestValidator.notEquals(
    "gallery order should change",
    reordered.data.map((image) => image.id).join(","),
    createdImages.map((image) => image.id).join(","),
  );
  TestValidator.equals(
    "first image becomes thumbnail",
    reordered.data[0].id,
    createdImages[2].id,
  );
  TestValidator.predicate(
    "first image should be main",
    reordered.data[0].isMain,
  );
  TestValidator.predicate(
    "all reordered images should preserve the same set",
    reordered.data.every((image) =>
      createdImages.some((original) => original.id === image.id),
    ),
  );
}

