export async function test_api_product_image_reorder_by_non_owner_rejected(
  connection: api.IConnection,
): Promise<void> {
  /**
   * Test that a non-owner seller cannot reorder another seller's product images.
   *
   * Validates ownership enforcement for the product image reorder workflow by creating a product and image set under one seller, then authenticating a different seller and attempting to reorder the product's images through the customer-scoped endpoint.
   *
   * 1. Create an owning seller and a second non-owner seller with distinct credentials.
   * 2. Create a product under the owning seller and attach multiple images to establish a known order.
   * 3. Attempt to reorder the product images as the non-owner and expect the operation to be rejected.
   * 4. Confirm the original image order remains unchanged after the failed reorder attempt.
   */
  const ownerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(ownerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "1234",
    } satisfies IMallPlatformSeller.IJoin,
  });
  const product = await generate_random_mall_platform_seller_products_create(
    ownerConnection,
    {
      body: {
        name: RandomGenerator.name(),
        description: RandomGenerator.paragraph({ sentences: 3 }),
        categoryId: null,
        basePrice: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1>
        >(),
      },
    },
  );
  typia.assert(product);
  const firstImage =
    await generate_random_mall_platform_seller_products_images_create(
      ownerConnection,
      {
        params: { productId: product.id },
        body: {
          imageUrl: `https://example.com/${RandomGenerator.alphaNumeric(8)}.jpg`,
          sortOrder: 0,
          isMain: true,
        } satisfies IMallPlatformProductImage.ICreate,
      },
    );
  typia.assert(firstImage);
  const secondImage =
    await generate_random_mall_platform_seller_products_images_create(
      ownerConnection,
      {
        params: { productId: product.id },
        body: {
          imageUrl: `https://example.com/${RandomGenerator.alphaNumeric(8)}.jpg`,
          sortOrder: 1,
          isMain: false,
        } satisfies IMallPlatformProductImage.ICreate,
      },
    );
  typia.assert(secondImage);
  const originalOrder = [firstImage.id, secondImage.id];
  TestValidator.equals(
    "original main image should be first",
    firstImage.isMain,
    true,
  );
  TestValidator.equals(
    "original secondary image should not be main",
    secondImage.isMain,
    false,
  );
  const nonOwnerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(nonOwnerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "1234",
    } satisfies IMallPlatformSeller.IJoin,
  });
  await TestValidator.error(
    "non-owner seller cannot reorder another seller's product images",
    async () => {
      await api.functional.mallPlatform.customer.products.images.index(
        nonOwnerConnection,
        {
          productId: product.id,
          body: {
            images: [
              secondImage,
              firstImage,
            ] satisfies IMallPlatformProductImage.ISummary[],
            page: null,
            limit: null,
          } satisfies IMallPlatformProductImage.IRequest,
        },
      );
    },
  );
  TestValidator.equals(
    "existing image order should remain unchanged after rejected reorder",
    originalOrder,
    [firstImage.id, secondImage.id],
  );
  TestValidator.equals(
    "product thumbnail should remain unchanged",
    firstImage.isMain,
    true,
  );
}

