      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          imageUrl: `https://example.com/${RandomGenerator.alphaNumeric(8)}.png`,
          sortOrder: 1,
          isMain: false,
        } satisfies IMallPlatformProductImage.ICreate,
