        body: {
          mallPlatformSellerId: sellerAAuth.id,
          page: 1,
          limit: 10,
          sort: "created_at",
          direction: "desc",
        } satisfies IMallPlatformOrderItem.IRequest,
      },
    );
  typia.assert(sellerAOrderItems);
