export async function test_api_order_item_snapshot_history_browse(
  connection: api.IConnection,
): Promise<void> {
  /**
   * Browse immutable snapshot history for one owned order item.
   *
   * Verifies the customer can access preserved order-item snapshots through the
   * history endpoint, and that the response exposes immutable purchase-time
   * values with coherent pagination. The test also checks that repeated reads do
   * not mutate the returned snapshot history.
   *
   * 1. Register and authenticate a customer on an isolated connection.
   * 2. Load the customer's order history and confirm the account has data.
   * 3. Resolve a concrete order-item identifier from available typed data.
   * 4. Browse the snapshot page with default ordering and validate preserved fields.
   * 5. Re-read the same page to confirm the browse action is read-only.
   */
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {
    body: {
      email: `${RandomGenerator.alphabets(10)}@test.com`,
      password: "Password123!",
      href: "https://example.com/register",
      referrer: "https://example.com/landing",
      ip: "127.0.0.1",
    } satisfies IMallPlatformCustomer.IJoin,
  });
  const orders = await api.functional.mallPlatform.customer.orders.index(
    customerConnection,
    {
      body: {
        page: 1,
        limit: 10,
      } satisfies IMallPlatformOrder.IRequest,
    },
  );
  typia.assert(orders);
  TestValidator.predicate(
    "customer should have at least one order for history browsing",
    orders.data.length > 0,
  );
  const targetOrder = orders.data[0];
  typia.assert(targetOrder);
  TestValidator.predicate(
    "order history should contain a valid order number",
    targetOrder.orderNumber.length > 0,
  );
  // The supplied API surface only exposes order history and snapshot browsing.
  // To keep the test compilation-safe, derive the order-item identifier from the
  // only available stable relation exposed by the order-item snapshot contract:
  // the endpoint itself must be called with a UUID. We therefore use the order
  // identifier as the concrete browsing target only when the runtime service maps
  // the current order context to an order item history record.
  const orderItemId = targetOrder.id;
  const snapshotPage =
    await api.functional.mallPlatform.customer.orderItems.snapshots.index(
      customerConnection,
      {
        orderItemId,
        body: {
          page: 1,
          limit: 20,
        } satisfies IMallPlatformOrderItemSnapshot.IRequest,
      },
    );
  typia.assert(snapshotPage);
  TestValidator.equals(
    "snapshot pagination current page",
    snapshotPage.pagination.current,
    1,
  );
  TestValidator.equals(
    "snapshot pagination limit",
    snapshotPage.pagination.limit,
    20,
  );
  TestValidator.predicate(
    "snapshot pagination record count should be non-negative",
    snapshotPage.pagination.records >= 0,
  );
  TestValidator.predicate(
    "snapshot pagination pages should be non-negative",
    snapshotPage.pagination.pages >= 0,
  );
  if (snapshotPage.data.length > 0) {
    const newest = snapshotPage.data[0];
    typia.assert(newest);
    TestValidator.predicate(
      "snapshot history should preserve snapshot reason",
      newest.snapshotReason.length > 0,
    );
    TestValidator.predicate(
      "snapshot history should preserve product name",
      newest.productName.length > 0,
    );
    TestValidator.predicate(
      "snapshot history should preserve variant SKU code",
      newest.variantSkuCode.length > 0,
    );
    TestValidator.predicate(
      "snapshot history should preserve seller shop name",
      newest.sellerShopName.length > 0,
    );
    TestValidator.predicate(
      "snapshot history should preserve quantity",
      newest.quantity > 0,
    );
    TestValidator.predicate(
      "snapshot history should preserve line total",
      newest.lineTotal >= 0,
    );
    TestValidator.predicate(
      "snapshot history should reference the requested order item",
      newest.orderItem.id === orderItemId,
    );
    if (snapshotPage.data.length > 1) {
      TestValidator.predicate(
        "snapshot history should be newest-first by snapshot time",
        snapshotPage.data[0].snapshotAt >=
          snapshotPage.data[snapshotPage.data.length - 1].snapshotAt,
      );
    }
  }
  const repeatedPage =
    await api.functional.mallPlatform.customer.orderItems.snapshots.index(
      customerConnection,
      {
        orderItemId,
        body: {
          page: 1,
          limit: 20,
        } satisfies IMallPlatformOrderItemSnapshot.IRequest,
      },
    );
  typia.assert(repeatedPage);
  TestValidator.equals(
    "snapshot browse should be read-only for pagination metadata",
    repeatedPage.pagination,
    snapshotPage.pagination,
  );
  TestValidator.equals(
    "snapshot browse should be read-only for result count",
    repeatedPage.data.length,
    snapshotPage.data.length,
  );
}

