import { authorize_customer_refresh } from "../../../authorize/authorize_customer_refresh";

/**
 * Browse preserved variant option rows for an order item snapshot.
 *
 * Validates the authenticated customer browse flow for immutable variant option rows attached to an order item snapshot. The test checks that the response is a valid paginated page, that the page metadata is internally consistent, and that repeated requests with the same input return the same ordering.
 *
 * Because this endpoint exposes historical snapshot data, the test focuses on read-only browsing behavior, pagination integrity, and stable response ordering rather than mutation or fixture setup.
 *
 * 1. Register a customer account and establish an authenticated customer connection.
 * 2. Browse variant option rows for a scoped order item snapshot using pagination and sorting controls.
 * 3. Validate the returned page metadata and row shape, then repeat the request to confirm deterministic results.
 */
export async function test_api_order_item_snapshot_variant_options_browse(
  connection: api.IConnection,
): Promise<void> {
  const customerConnection: api.IConnection = { host: connection.host };
  const customer = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      href: "https://example.com/register",
      referrer: "https://example.com/landing",
      ip: null,
    } satisfies IMallPlatformCustomer.IJoin,
  });
  typia.assert(customer);
  const orderItemId = typia.random<string & tags.Format<"uuid">>();
  const orderItemSnapshotId = typia.random<string & tags.Format<"uuid">>();
  const request = {
    search: undefined,
    page: 1,
    limit: 10,
    sort: "+createdAt",
  } satisfies IMallPlatformOrderItemSnapshotVariantOption.IRequest;
  const first =
    await api.functional.mallPlatform.customer.orderItems.snapshots.variantOptions.index(
      customerConnection,
      {
        orderItemId,
        orderItemSnapshotId,
        body: request,
      },
    );
  typia.assert(first);
  const second =
    await api.functional.mallPlatform.customer.orderItems.snapshots.variantOptions.index(
      customerConnection,
      {
        orderItemId,
        orderItemSnapshotId,
        body: request,
      },
    );
  typia.assert(second);
  TestValidator.equals("pagination current page", first.pagination.current, 1);
  TestValidator.equals("pagination limit", first.pagination.limit, 10);
  TestValidator.equals(
    "pagination pages is consistent with records and limit",
    first.pagination.pages,
    first.pagination.limit > 0
      ? Math.ceil(first.pagination.records / first.pagination.limit)
      : 0,
  );
  TestValidator.equals(
    "repeated request returns same pagination metadata",
    second.pagination,
    first.pagination,
  );
  TestValidator.equals(
    "repeated request returns same data rows",
    second.data,
    first.data,
  );
  TestValidator.predicate(
    "returned rows do not exceed the requested page size",
    first.data.length <= first.pagination.limit,
  );
  for (const row of first.data) {
    typia.assert(row);
    TestValidator.predicate(
      "row has snapshot context",
      row.orderItemSnapshot.id.length > 0,
    );
    TestValidator.predicate(
      "row has preserved option name",
      row.optionName.length > 0,
    );
    TestValidator.predicate(
      "row has preserved option value",
      row.optionValue.length > 0,
    );
    TestValidator.predicate(
      "row has createdAt timestamp",
      row.createdAt.length > 0,
    );
    TestValidator.predicate(
      "row has updatedAt timestamp",
      row.updatedAt.length > 0,
    );
    TestValidator.equals("row is not deleted", row.deletedAt, null);
    TestValidator.predicate(
      "row snapshot references an order item",
      row.orderItemSnapshot.orderItem.id.length > 0,
    );
  }
}

