export async function test_api_shipment_update_tracking_details(
  connection: api.IConnection,
): Promise<void> {
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerEmail = `${RandomGenerator.alphaNumeric(8)}@test.com`;
  const sellerPassword = RandomGenerator.alphaNumeric(12);
  await authorize_seller_join(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    } satisfies IMallPlatformSeller.IJoin,
  });
  const shipment = await api.functional.mallPlatform.seller.shipments.create(
    sellerConnection,
    {
      body: {
        carrierName: RandomGenerator.name(2),
        trackingNumber: RandomGenerator.alphaNumeric(16),
        shipmentItems: [
          {
            orderItemIds: [typia.random<string & tags.Format<"uuid">>()],
          } satisfies IMallPlatformShipmentItem.ICreate,
        ],
      } satisfies IMallPlatformShipment.ICreate,
    },
  );
  typia.assert(shipment);
  const originalShipmentId = shipment.id;
  const originalSeller = shipment.seller;
  const originalOrder = shipment.order;
  const originalShipmentItems = shipment.shipmentItems;
  const updatedCarrierName = `${shipment.carrierName} updated`;
  const updatedTrackingNumber = `${shipment.trackingNumber}X`;
  const updatedTrackingUrl = `https://tracking.example.com/${RandomGenerator.alphaNumeric(10)}`;
  const updatedStatus = "delivered";
  const updatedShippedAt = new Date(Date.now() - 1000 * 60 * 60).toISOString();
  const updatedDeliveredAt = new Date().toISOString();
  const updated = await api.functional.mallPlatform.seller.shipments.update(
    sellerConnection,
    {
      shipmentId: shipment.id,
      body: {
        carrierName: updatedCarrierName,
        trackingNumber: updatedTrackingNumber,
        trackingUrl: updatedTrackingUrl,
        status: updatedStatus,
        shippedAt: updatedShippedAt,
        deliveredAt: updatedDeliveredAt,
      } satisfies IMallPlatformShipment.IUpdate,
    },
  );
  typia.assert(updated);
  TestValidator.equals(
    "shipment id should remain the same",
    updated.id,
    originalShipmentId,
  );
  TestValidator.equals(
    "seller context should remain the same",
    updated.seller,
    originalSeller,
  );
  TestValidator.equals(
    "order context should remain the same",
    updated.order,
    originalOrder,
  );
  TestValidator.equals(
    "shipment items should remain unchanged",
    updated.shipmentItems,
    originalShipmentItems,
  );
  TestValidator.equals(
    "carrier name should be updated",
    updated.carrierName,
    updatedCarrierName,
  );
  TestValidator.equals(
    "tracking number should be updated",
    updated.trackingNumber,
    updatedTrackingNumber,
  );
  TestValidator.equals(
    "tracking url should be updated",
    updated.trackingUrl,
    updatedTrackingUrl,
  );
  TestValidator.equals(
    "status should be updated",
    updated.status,
    updatedStatus,
  );
  TestValidator.equals(
    "shippedAt should be updated",
    updated.shippedAt,
    updatedShippedAt,
  );
  TestValidator.equals(
    "deliveredAt should be updated",
    updated.deliveredAt,
    updatedDeliveredAt,
  );
  const reloaded = await api.functional.mallPlatform.seller.shipments.update(
    sellerConnection,
    {
      shipmentId: shipment.id,
      body: {
        carrierName: updatedCarrierName,
        trackingNumber: updatedTrackingNumber,
        trackingUrl: updatedTrackingUrl,
        status: updatedStatus,
        shippedAt: updatedShippedAt,
        deliveredAt: updatedDeliveredAt,
      } satisfies IMallPlatformShipment.IUpdate,
    },
  );
  typia.assert(reloaded);
  TestValidator.equals(
    "updated tracking data should persist on re-read",
    reloaded,
    updated,
  );
}

