export async function test_api_cancellation_request_snapshot_empty_history(
  connection: api.IConnection,
): Promise<void> {
  /**
   * Verifies that browsing cancellation request snapshots for an empty history returns a valid empty page.
   *
   * This test authenticates a customer, calls the nested snapshot history endpoint with a valid UUID route pair,
   * and asserts that the endpoint behaves as a read-only pagination browse operation when no snapshots exist.
   *
   * 1. Register and authenticate a customer account.
   * 2. Request the first page of snapshots for a nested order-item/cancellation-request pair.
   * 3. Validate the empty pagination metadata and data array.
   * 4. Repeat the same browse request to confirm it remains side-effect free.
   */
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "Test1234!",
      href: "https://example.com/signup",
      referrer: "https://example.com/landing",
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IMallPlatformCustomer.IJoin,
  });
  const orderItemId = typia.random<string & tags.Format<"uuid">>();
  const cancellationRequestId = typia.random<string & tags.Format<"uuid">>();
  const body = {
    page: 1,
    limit: 10,
  } satisfies IMallPlatformCancellationRequestSnapshot.IRequest;
  const first =
    await api.functional.mallPlatform.customer.orderItems.cancellationRequests.snapshots.index(
      customerConnection,
      {
        orderItemId,
        cancellationRequestId,
        body,
      },
    );
  typia.assert(first);
  TestValidator.equals(
    "empty snapshot page current",
    first.pagination.current,
    1,
  );
  TestValidator.equals("empty snapshot page limit", first.pagination.limit, 10);
  TestValidator.equals(
    "empty snapshot page records",
    first.pagination.records,
    0,
  );
  TestValidator.equals("empty snapshot page pages", first.pagination.pages, 0);
  TestValidator.equals("empty snapshot page data", first.data, []);
  const second =
    await api.functional.mallPlatform.customer.orderItems.cancellationRequests.snapshots.index(
      customerConnection,
      {
        orderItemId,
        cancellationRequestId,
        body,
      },
    );
  typia.assert(second);
  TestValidator.equals(
    "repeat snapshot page current",
    second.pagination.current,
    first.pagination.current,
  );
  TestValidator.equals(
    "repeat snapshot page limit",
    second.pagination.limit,
    first.pagination.limit,
  );
  TestValidator.equals(
    "repeat snapshot page records",
    second.pagination.records,
    first.pagination.records,
  );
  TestValidator.equals(
    "repeat snapshot page pages",
    second.pagination.pages,
    first.pagination.pages,
  );
  TestValidator.equals("repeat snapshot page data", second.data, first.data);
}

