      adminConnection,
      {
        orderItemId,
        body,
      },
    );
  typia.assert(output);
  TestValidator.predicate(
    "pagination current page is first page",
    output.pagination.current === 1,
  );
  TestValidator.predicate(
    "pagination limit is positive",
    output.pagination.limit > 0,
  );
