export async function test_api_refund_request_retrieve_scope_mismatch(
  connection: api.IConnection,
): Promise<void> {
  /**
   * Verify refund-request retrieval rejects scope mismatches and inactive lookups.
   *
   * This test validates that a refund request cannot be retrieved unless it belongs to the supplied order item scope.
   * It also covers the case where the lookup target is no longer active, ensuring the endpoint behaves as a business lookup failure.
   *
   * 1. Register and authenticate a customer account.
   * 2. Attempt to retrieve a refund request using mismatched order-item and refund-request identifiers.
   * 3. Attempt a second lookup with another mismatched identifier pair to represent an inactive or deleted-request case.
   * 4. Confirm both lookups fail without relying on mutated state or invented resource fields.
   */
  const customerConnection: api.IConnection = { host: connection.host };
  const authorized = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
