      referrer: "https://example.com/landing",
      ip: null,
    } satisfies IMallPlatformCustomer.IJoin,
  });
  typia.assert(authorized);
  const authenticatedCustomerConnection: api.IConnection = {
    host: connection.host,
    headers: {
      Authorization: authorized.token.access,
    },
  };
  const orderItemId = typia.random<string & tags.Format<"uuid">>();
  const refundRequestId = typia.random<string & tags.Format<"uuid">>();
  const alternateRefundRequestId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error(
    "refund request retrieval should fail for mismatched order-item scope",
    async () => {
      await api.functional.mallPlatform.customer.orderItems.refundRequests.at(
        authenticatedCustomerConnection,
        {
          orderItemId,
          refundRequestId,
        },
      );
    },
  );
  await TestValidator.error(
    "refund request retrieval should fail for inactive or deleted request lookup",
    async () => {
      await api.functional.mallPlatform.customer.orderItems.refundRequests.at(
        authenticatedCustomerConnection,
        {
          orderItemId,
          refundRequestId: alternateRefundRequestId,
        },
      );
    },
  );
}

