/**
 * Test refund request snapshot history scoping by parent order item and refund request identifiers.
 *
 * This scenario validates that immutable refund-request snapshot history cannot be accessed through a mismatched parent path. It ensures the endpoint enforces the relationship between the order item and the refund request before exposing any snapshot rows.
 *
 * 1. Authenticate a seller using an isolated seller connection.
 * 2. Call the refund-request snapshot history endpoint with deliberately mismatched order item and refund request identifiers.
 * 3. Confirm the server rejects the request as not found, preventing cross-parent history disclosure.
 */
export async function test_api_refund_request_snapshot_history_parent_scope(
  connection: api.IConnection,
): Promise<void> {
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
    } satisfies IMallPlatformSeller.IJoin,
  });
  const orderItemId = typia.random<string & tags.Format<"uuid">>();
  const refundRequestId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError(
    "refund request snapshot history must be scoped to the parent order item",
    404,
    async () => {
      await api.functional.mallPlatform.seller.orderItems.refundRequests.snapshots.index(
        sellerConnection,
        {
          orderItemId,
          refundRequestId,
          body: {
            page: 1,
            limit: 10,
          } satisfies IMallPlatformRefundRequestSnapshot.IRequest,
        },
      );
    },
  );
}

