export async function test_api_product_snapshot_images_list_history(
  connection: api.IConnection,
): Promise<void> {
  /**
   * Verify the seller-scoped product snapshot image history endpoint returns a paginated read-only view.
   *
   * This test authenticates a seller using the dedicated join utility, then calls the historical
   * product snapshot image listing endpoint for a UUID placeholder snapshot identifier. It validates
   * that the response structure is a proper page of preserved image records and that pagination
   * metadata is coherent regardless of whether the backend returns data for the provided snapshot.
   *
   * 1. Authenticate as a seller through a separate connection.
   * 2. Call the product snapshot image history endpoint with pagination parameters.
   * 3. Validate the returned page structure and immutable summary fields.
   */
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "password1234",
    } satisfies IMallPlatformSeller.IJoin,
  });
  const productSnapshotId = typia.random<string & tags.Format<"uuid">>();
  const request = {
    page: 1,
    limit: 10,
  } satisfies IMallPlatformProductSnapshotImage.IRequest;
  const output =
    await api.functional.mallPlatform.seller.productSnapshots.images.index(
      sellerConnection,
      {
        productSnapshotId,
        body: request,
      },
    );
  typia.assert(output);
  TestValidator.equals(
    "current page should match the requested page",
    output.pagination.current,
    request.page ?? 1,
  );
  TestValidator.equals(
    "page size should match the requested limit",
    output.pagination.limit,
    request.limit ?? 0,
  );
  TestValidator.predicate(
    "record count should be non-negative",
    output.pagination.records >= 0,
  );
  TestValidator.predicate(
    "page count should be non-negative",
    output.pagination.pages >= 0,
  );
  TestValidator.predicate(
    "returned data should be an array",
    Array.isArray(output.data),
  );
  if (output.data.length > 0) {
    const first = output.data[0]!;
    typia.assert(first.productSnapshot);
    TestValidator.equals(
      "snapshot image should preserve its parent snapshot id",
      first.productSnapshot.id,
      first.productSnapshot.id,
    );
    TestValidator.predicate(
      "snapshot image URI should be non-empty",
      first.imageUri.length > 0,
    );
    TestValidator.predicate(
      "snapshot image sort order should be an integer",
      Number.isInteger(first.sortOrder),
    );
    TestValidator.predicate(
      "snapshot image createdAt should be non-empty",
      first.createdAt.length > 0,
    );
  }
}

