    finalized.status,
    "approved",
  );
  TestValidator.equals(
    "reviewedAt should be recorded",
    finalized.reviewedAt,
    updateBody.reviewedAt,
  );
  TestValidator.equals(
    "approved requests should not store a rejection reason",
    finalized.rejectionReason,
    null,
  );
}

