    await api.functional.mallPlatform.administrator.approval_requests.update(
      administratorConnection,
      {
        approvalRequestId: approvalRequest.id,
        body: {
          status: "approved",
        } satisfies IMallPlatformAdministratorApprovalRequest.IUpdate,
