export async function patchMallPlatformSellerStorefrontIdentitySnapshots(props: {
  seller: SellerPayload;
  body: IMallPlatformSellerProfileSnapshot.IRequest;
}): Promise<IPageIMallPlatformSellerProfileSnapshot.ISummary> {
  const sellerProfile =
    await MyGlobal.prisma.mall_platform_seller_profiles.findFirstOrThrow({
      where: {
        sellerAccount: {
          id: props.seller.id,
        },
      },
      select: {
        id: true,
      },
    });
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 100;
  const skip = (page - 1) * limit;
  const where = {
    seller_profile_id: sellerProfile.id,
    ...(props.body.search === undefined || props.body.search.length === 0
      ? {}
      : {
          OR: [
            {
              shop_name: {
                contains: props.body.search,
                mode: "insensitive",
