            {
              shop_description: {
                contains: props.body.search,
                mode: "insensitive",
              },
            },
            {
              logo_image_uri: {
                contains: props.body.search,
                mode: "insensitive",
              },
            },
          ],
        }),
  } satisfies Prisma.mall_platform_seller_profile_snapshotsWhereInput;
  const orderBy = (
    props.body.sort === "shop_name"
      ? { shop_name: props.body.order ?? "desc" }
      : { created_at: props.body.order ?? "desc" }
  ) satisfies Prisma.mall_platform_seller_profile_snapshotsOrderByWithRelationInput;
  const records =
