  if (existing !== null)
    throw new HttpException("Administrator email already exists", 409);
  const createdAtText = new Date().toISOString();
  const sessionExpiredAtText = new Date(
    Date.now() + 7 * 24 * 60 * 60 * 1000,
  ).toISOString();
