    pagination: {
      current: page,
      limit,
      records: recordsCount,
      pages: limit > 0 ? Math.ceil(recordsCount / limit) : 0,
    },
    data: await ArrayUtil.asyncMap(
      records,
      MallPlatformShippingAddressAtSummaryTransformer.transform,
    ),
  };
}

