    sort === "snapshot_status"
      ? [{ snapshot_status: order }, { id: order }]
      : sort === "review_result"
        ? [{ review_result: order }, { id: order }]
        : sort === "reason"
          ? [{ reason: order }, { id: order }]
          : sort === "changed_at"
            ? [{ changed_at: order }, { id: order }]
            : sort === "id"
              ? [{ id: order }]
              : [{ changed_at: "desc" }, { id: "desc" }];
  const records =
