export async function postMallPlatformAdministratorOrdersOrderIdForceCancel(props: {
  administrator: AdministratorPayload;
  orderId: string & tags.Format<"uuid">;
  body: IMallPlatformOrder.IForceCancel;
}): Promise<IMallPlatformOrder> {
  if (props.administrator.type !== "administrator") {
    throw new HttpException("Forbidden", 403);
  }
  if (props.body.scope !== "order") {
    throw new HttpException(
      "Only whole-order force cancellation is supported.",
      400,
    );
  }
  const order = await MyGlobal.prisma.mall_platform_orders.findUniqueOrThrow({
    where: { id: props.orderId },
    select: {
      id: true,
      status: true,
      orderItems: {
        select: {
          id: true,
          status: true,
        },
      },
    },
  });
  if (order.orderItems.length === 0) {
    throw new HttpException("Order has no items to cancel.", 400);
  }
  const cancellableStatuses = new Set(["paid", "processing"]);
  const invalidItem = order.orderItems.find(
    (item) => !cancellableStatuses.has(item.status),
  );
  if (invalidItem !== undefined) {
    throw new HttpException(
      "Order contains items that cannot be force-cancelled.",
      400,
    );
  }
  await MyGlobal.prisma.$transaction(async (prisma) => {
    await prisma.mall_platform_orders.update({
      where: { id: order.id },
      data: {
        status: "cancelled",
        updated_at: new Date(),
      },
    });
  });
  const record = await MyGlobal.prisma.mall_platform_orders.findUniqueOrThrow({
    where: { id: props.orderId },
    ...MallPlatformOrderTransformer.select(),
  });
  return await MallPlatformOrderTransformer.transform(record);
}

