export async function patchMallPlatformCustomerProductsProductIdReviews(props: {
  customer: CustomerPayload;
  productId: string & tags.Format<"uuid">;
  body: IMallPlatformReview.IRequest;
}): Promise<IPageIMallPlatformReview.ISummary> {
  await MyGlobal.prisma.mall_platform_products.findUniqueOrThrow({
    where: { id: props.productId },
    select: { id: true },
  });
  const page: number = props.body.page ?? 1;
  const limit: number = props.body.limit ?? 100;
  const skip: number = (page - 1) * limit;
  const where = {
    product_id: props.productId,
    deleted_at: null,
    ...(props.body.search !== undefined
      ? { content: { contains: props.body.search, mode: "insensitive" } }
      : {}),
  } satisfies Prisma.mall_platform_reviewsWhereInput;
  const orderBy =
    props.body.sort === "oldest"
      ? ({
          created_at: "asc",
        } satisfies Prisma.mall_platform_reviewsOrderByWithRelationInput)
      : ({
          created_at: "desc",
        } satisfies Prisma.mall_platform_reviewsOrderByWithRelationInput);
  const records = await MyGlobal.prisma.mall_platform_reviews.findMany({
    where,
    orderBy,
    skip,
    take: limit,
    ...MallPlatformReviewAtSummaryTransformer.select(),
  });
  const recordsCount = await MyGlobal.prisma.mall_platform_reviews.count({
    where,
  });
  return {
    pagination: {
      current: page,
      limit,
      records: recordsCount,
      pages: Math.ceil(recordsCount / limit),
    },
    data: await ArrayUtil.asyncMap(
      records,
      MallPlatformReviewAtSummaryTransformer.transform,
    ),
  };
}

